const input = $json.chatInput || "";

// Match the first URL
const urlMatch = input.match(/https?:\/\/[^\s]+/);
const url = urlMatch ? urlMatch[0] : "";

// Remove the URL from the original text
const question = input
  .replace(url, "")
  .replace(/\n+/g, " ")
  .replace(/\s+/g, " ")
  .trim();

return [
  {
    json: {
      url,
      question
    }
  }
];

const html = $json.data;

// Remove style and noscript blocks
let text = html
  .replace(/<style[\s\S]*?<\/style>/gi, " ")
  .replace(/<noscript[\s\S]*?<\/noscript>/gi, " ");

// Remove all script tags EXCEPT application/ld+json
text = text.replace(
  /<script\b(?![^>]*type=["']application\/ld\+json["'])[^>]*>[\s\S]*?<\/script>/gi,
  " "
);

// Remove HTML tags but keep the contents inside
text = text.replace(/<\/?[^>]+>/g, " ");

// Decode common HTML entities
const entities = {
  "&nbsp;": " ",
  "&amp;": "&",
  "&quot;": '"',
  "&#39;": "'",
  "&apos;": "'",
  "&lt;": "<",
  "&gt;": ">",
};

for (const [entity, value] of Object.entries(entities)) {
  text = text.split(entity).join(value);
}

// Remove URLs
text = text.replace(/https?:\/\/\S+/g, " ");

// Remove long hexadecimal hashes
text = text.replace(/\b[a-f0-9]{16,}\b/gi, " ");

// Keep readable characters INCLUDING JSON punctuation
text = text.replace(/[^\w\s.,:;!?%&'"\/(){}\[\]-]/g, " ");

// Collapse whitespace
text = text.replace(/\s+/g, " ").trim();

return [{
  json: {
    cleanedText: text
  }
}];

const html = $json.data;

// Extract all Shopify image URLs embedded in Next.js imageSrcSet
const regex = /https%3A%2F%2Fcdn\.shopify\.com%2F[^"&\s]+/gi;

const matches = html.match(regex) || [];

// Decode URLs
let urls = matches.map(url => decodeURIComponent(url));

// Remove query parameters
urls = urls.map(url => url.split("?")[0]);

// Remove duplicates
urls = [...new Set(urls)];

// Ignore non-product assets
const excludePatterns = [
  "PDP-promise",
  "pdp-faqs",
  "logo",
  "icon",
  "payment",
  "trust",
  "banner",
  "hero",
  "social",
  "facebook",
  "instagram",
  "twitter",
  "youtube",
  "favicon",
  "placeholder",
  "spinner",
  "loading"
];

const productImages = urls.filter(url => {
  const lower = url.toLowerCase();
  return !excludePatterns.some(pattern => lower.includes(pattern.toLowerCase()));
});

// Return as an array
return [{
  json: {
    productImages
  }
}];

const items = $input.all();

return [
  {
    json: {
      imageAnalysis: items[0].json.content.parts[0].text,
      textAnalysis: items[1].json.content.parts[0].text
    }
  }
];
